static int check_case(const Case *c) {
    unsigned char *dst = malloc(c->rlen ? c->rlen : 1);
    int err = 0;
    long n = wubu_inflate(c->comp, c->clen, dst, c->rlen ? c->rlen : 1, &err);
    if (err != 0 || n != (long)c->rlen) {
        printf("  [FAIL] %-14s err %d (%s) got %ld want %lu\n", c->name, err,
               wubu_inflate_reason(err), n, (unsigned long)c->rlen);
        free(dst); return 0;
    }
    int good = 1;
    if (c->raw) good = memcmp(dst, c->raw, c->rlen) == 0;
    else if (c->pattern && strcmp(c->pattern, "zero") == 0) {
        for (size_t i = 0; i < c->rlen && good; i++) good = dst[i] == 0;
    } else if (c->pattern) {
        for (size_t i = 0; i < c->rlen && good; i++) good = dst[i] == (unsigned char)c->pattern[i % 4];
    }
    if (!good) printf("  [FAIL] %-14s content differs\n", c->name);
    free(dst);
    return good;
}

static void refuses(const char *what, const unsigned char *src, size_t slen, size_t cap, int want) {
    unsigned char *dst = malloc(cap ? cap : 1);
    int err = 0;
    (void)wubu_inflate(src, slen, dst, cap, &err);
    if (err == want) pass++;
    else { printf("  [FAIL] %-22s expected %d, got %d (%s)\n", what, want, err, wubu_inflate_reason(err)); fail++; }
    free(dst);
}

int main(void) {
    printf("=== wubu_inflate (slerm gate, SLERM-2001) ===\n");
    for (size_t i = 0; i < sizeof CASES / sizeof CASES[0]; i++) {
        if (check_case(&CASES[i])) pass++; else fail++;
    }

    /* truncated: three bytes gone from the end, so the Adler-32 trailer is really payload */
    refuses("truncated", c_text_z6, sizeof c_text_z6 - 3, 8192, WUBU_INFLATE_TRUNCATED);
    /* a damaged checksum must be named as such */
    { static unsigned char bad[sizeof c_text_z6];
      memcpy(bad, c_text_z6, sizeof bad); bad[sizeof bad - 1] ^= 0xFF;
      refuses("bad adler32", bad, sizeof bad, 8192, WUBU_INFLATE_CHECKSUM); }
    /* a flipped payload byte must never come back OK -- any named refusal is fine */
    { static unsigned char bad[sizeof c_text_z6];
      memcpy(bad, c_text_z6, sizeof bad); bad[4] ^= 0xFF;
      int err = 0; unsigned char out[8192];
      long n = wubu_inflate(bad, sizeof bad, out, sizeof out, &err);
      if (n == -1 && err != WUBU_INFLATE_OK) pass++;
      else { printf("  [FAIL] corrupt payload came back err=%d n=%ld\n", err, n); fail++; } }

    /* A reachable false positive, built by hand: a RAW stored block whose first two
     * bytes (0x08, 0x1d) form a valid zlib header -- CM=8, CINFO=0, FCHECK sums to
     * zero, FDICT clear. LEN is 29 and lives in bytes 1-2, so the same two bytes are
     * both a zlib header and a stored-block length: the collision is real, not
     * contrived. Auto-detection must fall back to raw, not refuse. */
    { static const unsigned char payload[] = { 0x41, 0x42, 0x43, 0x44, 0x45, 0x46, 0x47, 0x48, 0x49, 0x4a, 0x4b, 0x4c, 0x4d, 0x4e, 0x4f, 0x50, 0x51, 0x52, 0x53, 0x54, 0x55, 0x56, 0x57, 0x58, 0x59, 0x5a, 0x41, 0x42, 0x43 };
      static unsigned char fp[sizeof payload + 10];
      memcpy(fp, (const unsigned char[]){ 0x08, 0x1d, 0x00, 0xE2, 0xFF }, 5);
      memcpy(fp + 5, payload, sizeof payload);
      memcpy(fp + 5 + sizeof payload, (const unsigned char[]){ 0x01, 0x00, 0x00, 0xFF, 0xFF }, 5);
      if ((((fp[0] << 8) | fp[1]) % 31) != 0 || (fp[0] & 0x0F) != 8) {
          printf("  [FAIL] false-positive vector is not a valid zlib header\n"); fail++;
      } else {
          unsigned char out[128]; int err = 0;
          long n = wubu_inflate(fp, sizeof fp, out, sizeof out, &err);
          if (n == (long)sizeof payload && !memcmp(out, payload, sizeof payload)) pass++;
          else { printf("  [FAIL] zlib-looking raw stream: err %d n %ld\n", err, n); fail++; }
      } }
    refuses("dst too small", c_zeros32k_z9, sizeof c_zeros32k_z9, 1024, WUBU_INFLATE_OVERFLOW);
    { static const unsigned char b3[] = { 0x07 }; refuses("block type 3", b3, 1, 64, WUBU_INFLATE_BAD_BLOCK); }
    { static const unsigned char dict[] = { 0x78, 0xBB, 0x00, 0x00, 0x00, 0x00 };
      refuses("preset dictionary", dict, sizeof dict, 64, WUBU_INFLATE_DICT); }
    { int err = 0; if (wubu_inflate(NULL, 4, NULL, 4, &err) == -1 && err == WUBU_INFLATE_ARGS) pass++;
      else { printf("  [FAIL] null arguments\n"); fail++; } }

    if (wubu_adler32((const unsigned char *)"Wikipedia", 9) == 0x11E60398UL) pass++;
    else { printf("  [FAIL] adler32(Wikipedia) != 0x11E60398\n"); fail++; }

    printf("\n=== %d passed, %d failed ===\n", pass, fail);
    return fail ? 1 : 0;
}
